using Godot;
using System;
using System.Linq;
using System.Collections.Generic;
using GArray=Godot.Collections.Array;
using Settings=Godot.Collections.Dictionary;
public partial class ActorTimelineOperations
{
    private readonly ActorAnimationOperations _animation=new();private readonly ActorAnimationTrackOperations _tracks=new();private readonly Expression _timelineEquality=CreateTimelineEquality();
    private static Expression CreateTimelineEquality(){var expression=new Expression();expression.Parse("a == b",new[]{"a","b"});return expression;}
    private bool Equal(Variant a,Variant b)=>_timelineEquality.Execute(new GArray{a,b}).AsBool();
    private static Resource NewAnimationResource(string name)=>name switch{"actor_keyframe"=>new ActorKeyframe(),"actor_animation_track"=>new ActorAnimationTrack(),_=>throw new ArgumentException("Unknown animation resource: "+name)};
    private static bool Path(Resource track,string[] path)=>track.Get("path").AsStringArray().SequenceEqual(path);
    public GArray animation_snapshot(Resource actor){var result=actor.Get("animation_tracks").AsGodotArray().Duplicate();result.Clear();foreach(var value in actor.Get("animation_tracks").AsGodotArray())result.Add(_tracks.copy_track(value.As<Resource>()));return result;}
    public string[] object_animation_path(Resource actor,Resource resource,StringName key){var path=_animation.path_to_object(actor,resource);if(path.Length==0)return path;return path.Append(key.ToString()).ToArray();}
    public void preview_animation_value(RefCounted owner,Resource actor,string[] path,Variant value){var previews=actor.Get("animation_previews").AsGodotDictionary();string id=string.Join(" / ",path);previews.Remove(id);var track=_data.animation_track(actor,path);var clip=clip_for_actor_id(owner,actor.Get("id").AsString());if(track==null||clip==null||!Equal(_animation.sampled_value(actor,path,_runtime.local_time(clip,owner.Get("playhead_time").AsDouble()),default),value))previews[id]=new Settings{["path"]=(string[])path.Clone(),["value"]=_data.copy_value(value)};actor.EmitChanged();Changed(owner);}
    public void commit_animation_value(RefCounted owner,Resource actor,string[] path,Variant value){actor.Get("animation_previews").AsGodotDictionary().Remove(string.Join(" / ",path));var clip=clip_for_actor_id(owner,actor.Get("id").AsString());var track=_data.animation_track(actor,path);if(track==null||clip==null)return;if(Equal(_animation.sampled_value(actor,path,_runtime.local_time(clip,owner.Get("playhead_time").AsDouble()),default),value)){Changed(owner);return;}var keys=track.Get("keys").AsGodotArray();add_keyframe(owner,actor,path,track.Get("label").AsString(),value,keys.Count>0&&keys[0].As<Resource>().Get("interpolation").AsInt32()==2,true);}
    public bool animated_object_edit(RefCounted owner,Resource actor,Resource resource,StringName key,Variant value,bool preview){var path=object_animation_path(actor,resource,key);if(path.Length==0||_data.animation_track(actor,path)==null)return false;if(preview)preview_animation_value(owner,actor,path,value);else commit_animation_value(owner,actor,path,value);return true;}
    public void edit_shader_uniform(RefCounted owner,Resource actor,Resource resource,Resource definition,StringName name,Variant value,string mode,Variant original)
    {
        var path=object_animation_path(actor,resource,"uniforms").Append(name.ToString()).ToArray();if(_data.animation_track(actor,path)!=null){if(mode=="preview")preview_animation_value(owner,actor,path,value);else commit_animation_value(owner,actor,path,value);return;}var property=_definitions.find_property(definition,"uniforms")!;var uniforms=_definitions.value_for(resource,property).AsGodotDictionary().Duplicate(true);uniforms[name]=_data.copy_value(value);if(mode=="preview")owner.Call("preview_object_property",actor,resource,definition,new StringName("uniforms"),uniforms);else if(mode=="commit"){var originalValues=original.VariantType==Variant.Type.Dictionary?original.AsGodotDictionary().Duplicate(true):new Settings();var parent=object_animation_path(actor,resource,"uniforms");var stored=_definitions.value_for(resource,property).AsGodotDictionary();foreach(var item in actor.Get("animation_tracks").AsGodotArray()){var trackPath=item.As<Resource>().Get("path").AsStringArray();if(trackPath.Length==parent.Length+1&&trackPath.Take(parent.Length).SequenceEqual(parent)){StringName animated=trackPath[^1];if(stored.TryGetValue(animated,out var previous))originalValues[animated]=previous;else originalValues.Remove(animated);}}owner.Call("commit_object_property_preview",actor,resource,definition,new StringName("uniforms"),originalValues,uniforms);}else owner.Call("edit_object_property",actor,resource,definition,new StringName("uniforms"),uniforms);
    }
    private Resource NewKey(double time){var key=NewAnimationResource("actor_keyframe");key.Set("id",_data.new_id());key.Set("time",time);return key;}
    public void add_keyframe(RefCounted owner,Resource? actor,string[] path,string label,Variant value,bool stepped,bool changedOnly)
    {
        var clip=actor!=null?clip_for_actor_id(owner,actor.Get("id").AsString()):null;if(actor==null||clip==null||path.Length==0||value.VariantType is not (Variant.Type.Float or Variant.Type.Int or Variant.Type.Bool or Variant.Type.String or Variant.Type.StringName or Variant.Type.Vector2 or Variant.Type.Vector3 or Variant.Type.Vector4 or Variant.Type.Vector2I or Variant.Type.Vector3I or Variant.Type.Vector4I or Variant.Type.Color))return;var before=animation_snapshot(actor);var after=animation_snapshot(actor);var current=_data.animation_track(actor,path);double time=_runtime.local_time(clip,owner.Get("playhead_time").AsDouble());if(current!=null&&current.Get("component").AsInt32()>=0){foreach(var item in after){var part=item.As<Resource>();if(!Path(part,path))continue;var component=value_component(value,part.Get("component").AsInt32());if(changedOnly&&Equal(_tracks.sample(part,time,default),component))continue;var key=_tracks.key_at(part,time);if(key==null){key=NewKey(time);part.Get("keys").AsGodotArray().Add(key);}key.Set("value",component);_tracks.sort_keys(part);}commit_animation_edit(owner,actor,before,after,"Set Component Keyframes");return;}Resource? track=null;foreach(var item in after){var candidate=item.As<Resource>();if(Path(candidate,path)){track=candidate;break;}}if(track==null){track=NewAnimationResource("actor_animation_track");track.Set("path",(string[])path.Clone());track.Set("label",label);after.Add(track);}var frame=_tracks.key_at(track,time);if(frame==null){frame=NewKey(time);track.Get("keys").AsGodotArray().Add(frame);}frame.Set("value",_data.copy_value(value));if(stepped||value.VariantType is Variant.Type.Bool or Variant.Type.Vector2I or Variant.Type.Vector3I or Variant.Type.Vector4I)frame.Set("interpolation",2);_tracks.sort_keys(track);var sorted=new List<Resource>();foreach(var item in after)sorted.Add(item.As<Resource>());using var compare=new Expression();compare.Parse("a.naturalnocasecmp_to(b)",new[]{"a","b"});sorted.Sort((a,b)=>a.Get("path").AsStringArray().SequenceEqual(b.Get("path").AsStringArray())?a.Get("component").AsInt32().CompareTo(b.Get("component").AsInt32()):compare.Execute(new GArray{a.Get("label"),b.Get("label")}).AsInt32());after.Clear();foreach(var item in sorted)after.Add(item);commit_animation_edit(owner,actor,before,after,"Set Keyframe");
    }
    public Resource? keyframe_for_id(Resource actor,string id){foreach(var item in actor.Get("animation_tracks").AsGodotArray())foreach(var value in item.As<Resource>().Get("keys").AsGodotArray()){var key=value.As<Resource>();if(key.Get("id").AsString()==id)return key;}return null;}
    public Resource? track_for_key(Resource actor,string id){foreach(var item in actor.Get("animation_tracks").AsGodotArray()){var track=item.As<Resource>();foreach(var value in track.Get("keys").AsGodotArray())if(value.As<Resource>().Get("id").AsString()==id)return track;}return null;}
    public int component_count(Variant value)=>value.VariantType switch{Variant.Type.Vector2 or Variant.Type.Vector2I=>2,Variant.Type.Vector3 or Variant.Type.Vector3I=>3,Variant.Type.Vector4 or Variant.Type.Vector4I or Variant.Type.Color=>4,_=>0};
    public Variant value_component(Variant value,int axis)=>ActorAnimationOperations.Component(value,axis);
    public void separate_track(RefCounted owner,Resource actor,string[] path)
    {
        var source=_data.animation_track(actor,path);if(source==null||source.Get("component").AsInt32()>=0||source.Get("keys").AsGodotArray().Count==0)return;var value=source.Get("keys").AsGodotArray()[0].As<Resource>().Get("value");int count=component_count(value);if(count==0)return;var before=animation_snapshot(actor);var after=animation_snapshot(actor);for(int i=after.Count-1;i>=0;i--)if(Path(after[i].As<Resource>(),path))after.RemoveAt(i);int index=actor.Get("animation_tracks").AsGodotArray().IndexOf(source);for(int axis=0;axis<count;axis++){var part=_tracks.copy_track(source);part.Set("component",axis);part.Set("component_base",_data.copy_value(value));part.Set("label",part.Get("label").AsString()+" / "+(value.VariantType==Variant.Type.Color?new[]{"R","G","B","A"}:new[]{"X","Y","Z","W"})[axis]);foreach(var item in part.Get("keys").AsGodotArray()){var key=item.As<Resource>();key.Set("id",_data.new_id());key.Set("value",value_component(key.Get("value"),axis));}after.Insert(index+axis,part);}commit_animation_edit(owner,actor,before,after,"Separate Keyframe Components");
    }
    public void unseparate_track(RefCounted owner,Resource actor,string[] path)
    {
        var source=_data.animation_track(actor,path);if(source==null||source.Get("component").AsInt32()<0)return;var before=animation_snapshot(actor);var after=before.Duplicate();after.Clear();var times=new SortedSet<double>();foreach(var item in before){var track=item.As<Resource>();if(!Path(track,path))after.Add(track);else foreach(var value in track.Get("keys").AsGodotArray())times.Add(value.As<Resource>().Get("time").AsDouble());}var joined=NewAnimationResource("actor_animation_track");joined.Set("path",(string[])path.Clone());string label=source.Get("label").AsString();joined.Set("label",label.Substring(0,Math.Max(0,label.Length-4)));foreach(double time in times){var key=NewKey(time);key.Set("value",_animation.sampled_value(actor,path,time,default));var original=_tracks.key_at(source,time);if(original!=null){var curve=original.Get("value_curve").As<Curve>();key.Set("value_curve",curve!=null?Variant.From(curve.Duplicate()):default);foreach(string field in new[]{"curve_template","curve_adjustment","interpolation","attenuation"})key.Set(field,original.Get(field));}joined.Get("keys").AsGodotArray().Add(key);}after.Add(joined);commit_animation_edit(owner,actor,before,after,"Unseparate Keyframe Components");
    }
    public bool preview_keyframe(RefCounted owner,Resource actor,string id,Settings changes)
    {
        var key=keyframe_for_id(actor,id);if(key==null)return false;if(changes.TryGetValue("value",out var changed)&&changed.VariantType!=key.Get("value").VariantType)return false;if(changes.TryGetValue("attenuation",out var attenuation)&&!double.IsFinite(attenuation.AsDouble()))return false;if(changes.TryGetValue("time",out var next)){double time=next.AsDouble();if(!double.IsFinite(time))return false;foreach(var item in actor.Get("animation_tracks").AsGodotArray()){var track=item.As<Resource>();if(!track.Get("keys").AsGodotArray().Contains(key))continue;var occupied=_tracks.key_at(track,time);if(occupied!=null&&occupied!=key)return false;}key.Set("time",time);}if(changes.TryGetValue("value",out changed))key.Set("value",_data.copy_value(changed));if(changes.TryGetValue("value_curve",out var curveValue)){var curve=curveValue.VariantType==Variant.Type.Object?curveValue.AsGodotObject() as Curve:null;key.Set("value_curve",curve!=null?Variant.From(curve.Duplicate()):default);key.Set("interpolation",0);key.Set("curve_template",Get(changes,"curve_template",""));}if(changes.TryGetValue("curve_adjustment",out var adjustment))key.Set("curve_adjustment",adjustment.AsDouble());if(changes.TryGetValue("interpolation",out var interpolation))key.Set("interpolation",Math.Clamp(interpolation.AsInt32(),0,2));if(changes.TryGetValue("attenuation",out attenuation))key.Set("attenuation",attenuation.AsDouble());foreach(var item in actor.Get("animation_tracks").AsGodotArray())_tracks.sort_keys(item.As<Resource>());actor.EmitChanged();Changed(owner);return true;
    }
    public void edit_keyframe(RefCounted owner,Resource actor,string id,Settings changes){var before=animation_snapshot(actor);if(preview_keyframe(owner,actor,id,changes))commit_animation_edit(owner,actor,before,animation_snapshot(actor),"Edit Keyframe");}
    public void delete_keyframes(RefCounted owner,Resource actor,GArray ids){var before=animation_snapshot(actor);var after=animation_snapshot(actor);foreach(var item in after){var keys=item.As<Resource>().Get("keys").AsGodotArray();for(int i=keys.Count-1;i>=0;i--)if(ids.Contains(keys[i].As<Resource>().Get("id")))keys.RemoveAt(i);}for(int i=after.Count-1;i>=0;i--)if(after[i].As<Resource>().Get("keys").AsGodotArray().Count==0)after.RemoveAt(i);commit_animation_edit(owner,actor,before,after,"Delete Keyframes");}
    public void commit_animation_edit(RefCounted owner,Resource actor,GArray before,GArray after,string label){if(!Actors(owner).Contains(actor))return;if(owner.Get("property_batch_active").AsBool()){restore_animation(owner,actor,after);return;}History(owner,label,"restore_animation",new GArray{actor,after},"restore_animation",new GArray{actor,before});}
    public void restore_animation(RefCounted owner,Resource actor,GArray tracks){var copy=tracks.Duplicate();var target=actor.Get("animation_tracks").AsGodotArray();target.Clear();foreach(var item in copy)target.Add(_tracks.copy_track(item.As<Resource>()));actor.EmitChanged();Changed(owner);}
}
